<?php use App\Support\App;App::requireAdmin();$title='Settings';require __DIR__.'/../layouts/head.php';?><main class="p-8 max-w-4xl mx-auto"><h1 class="text-2xl font-semibold">Website & Gateway Settings</h1><form id="f" class="saas-card p-6 mt-6 space-y-4"><input class="field" name="site_name" value="<?=htmlspecialchars(App::setting('site_name','CEKSINYAL'))?>"><label><input type="checkbox" name="gateway_manual" value="1"> Manual</label><label><input type="checkbox" name="gateway_gobiz" value="1"> GoBiz</label><label><input type="checkbox" name="gateway_jago" value="1"> Jago</label><button class="btn btn-dark">Save</button></form></main><script>f.onsubmit=async e=>{e.preventDefault();let fd=new FormData(f),o=Object.fromEntries(fd);for(let k of ['gateway_manual','gateway_gobiz','gateway_jago'])o[k]=fd.has(k)?1:0;let r=await fetch('/api/admin/settings',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':'<?=App::csrf()?>'},body:JSON.stringify(o)});Swal.fire(JSON.stringify(await r.json()))}</script><?php require __DIR__.'/../layouts/foot.php';?>